const input = $input.first()?.json || {};
const DEFAULT_CHAT_ID = "1519369571"; // Founder Telegram Chat ID
const botToken = "YOUR_TELEGRAM_BOT_TOKEN";

const sendTg = async (chatId, htmlText) => {
  try {
    await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.telegram.org/bot" + botToken + "/sendMessage",
      headers: { "Content-Type": "application/json" },
      body: {
        chat_id: chatId,
        text: htmlText,
        parse_mode: "HTML"
      },
      json: true
    });
  } catch (e) {
    console.log("Send TG error: " + e.message);
  }
};

// 1. Detect Callback Query (Button click on Telegram preview)
const cq = input.callback_query || input.body?.callback_query;
if (cq && (cq.data || cq.id)) {
  const callbackId = String(cq.id || "");
  const callbackData = String(cq.data || "").trim();
  const chatId = String(cq.message?.chat?.id || cq.from?.id || DEFAULT_CHAT_ID);
  const messageId = cq.message?.message_id;
  const messageText = cq.message?.text || "";
  const messageCaption = cq.message?.caption || "";

  // If button was already locked/completed, show native Telegram alert and stop immediately
  if (callbackData === "locked" || callbackData === "none") {
    try {
      await this.helpers.httpRequest({
        method: "POST",
        url: "https://api.telegram.org/bot" + botToken + "/answerCallbackQuery",
        body: {
          callback_query_id: callbackId,
          text: "🔒 Bu taslak için işlem zaten yapıldı ve buton kilitlendi.",
          show_alert: true
        },
        json: true
      });
    } catch (e) {}
    return [];
  }

  return [{ json: { eventType: "callback", callbackId, callbackData, chatId, messageId, messageText, messageCaption, timestamp: new Date().toISOString() } }];
}

// 2. Detect Telegram Text Commands & Natural Language Intents
const msg = input.message || input.msg;
if (msg && msg.text) {
  const rawText = String(msg.text).trim();
  const text = rawText.toLowerCase();
  const chatId = String(msg.chat?.id || msg.from?.id || DEFAULT_CHAT_ID);

  // Publish / Approve intent ("publish and go", "publish", "/publish", "approve", "yayınla", "onayla")
  if (
    text.includes("publish") ||
    text.includes("yayınla") ||
    text.includes("yayinla") ||
    text.includes("onayla") ||
    text.includes("approve") ||
    text.startsWith("/publish") ||
    text.startsWith("/approve")
  ) {
    return [{ json: { 
      eventType: "callback", 
      callbackId: "", 
      callbackData: "approve", 
      chatId, 
      messageId: msg.message_id,
      messageText: msg.reply_to_message?.text || "", 
      messageCaption: msg.reply_to_message?.caption || "", 
      timestamp: new Date().toISOString() 
    } }];
  }

  // Redo / Reject intents
  if (text.includes("redo") || text.includes("tekrar") || text.includes("yeniden")) {
    return [{ json: { eventType: "callback", callbackId: "", callbackData: "redo", chatId, timestamp: new Date().toISOString() } }];
  }
  if (text.includes("reject") || text.includes("reddet") || text.includes("iptal")) {
    return [{ json: { eventType: "callback", callbackId: "", callbackData: "reject", chatId, timestamp: new Date().toISOString() } }];
  }

  // Status check
  if (text.startsWith("/status") || text.includes("durum") || text === "status") {
    let lastDraftInfo = "Henüz hazırda bekleyen taslak bulunmuyor.";
    try {
      const fs = require("fs");
      const draftPath = "/home/node/.n8n-files/studio-images/current_draft.json";
      if (fs.existsSync(draftPath)) {
        const d = JSON.parse(fs.readFileSync(draftPath, "utf8"));
        const lockStatus = d.isPublished || d.status === "published" ? "✅ Yayınlandı (Kilitli)" : (d.status === "rejected" ? "❌ Reddedildi (Kilitli)" : (d.status === "redone" ? "🔄 Yeniden Üretildi" : "🟡 Beklemede"));
        lastDraftInfo = "📌 <b>Son Taslak:</b> " + (d.hookTitle || "Bilinmiyor") + "\n🖼️ <b>Görseller:</b> " + (d.slides?.length || 0) + " slayt\n🔒 <b>Durum:</b> " + lockStatus + "\n🆔 <b>ID:</b> <code>" + (d.draftId || "N/A") + "</code>";
      }
    } catch (e) {}

    await sendTg(chatId, "📊 <b>Instagram Content Engine Durumu</b>\n━━━━━━━━━━━━━━━━━━━━\n✅ <b>Sistem:</b> Aktif ve Çalışıyor\n📱 <b>Instagram:</b> @developmentserhat\n" + lastDraftInfo + "\n\n👉 <i>Yeni bir post üretmek için /generate veya /create yazabilirsiniz.</i>");
    return [];
  }

  // Help / Start intent
  if (text.startsWith("/help") || text.startsWith("/start") || text === "yardım" || text === "yardim") {
    await sendTg(chatId, "👋 <b>Instagram İçerik & Yayın Asistanı</b>\n━━━━━━━━━━━━━━━━━━━━\nKullanabileceğiniz komutlar:\n\n• <b>/generate</b> veya <b>/create</b>: Yapay zeka ile 3 slaytlık yeni bir Instagram carousel taslağı üretir.\n• <b>publish and go</b> veya <b>/publish</b>: Hazır olan son taslağı doğrudan @developmentserhat hesabında yayınlar (tek kullanımlıktır, tekrar yayınlanamaz).\n• <b>/status</b>: Sistemin ve mevcut taslağın durumunu gösterir.\n\nHer taslak sadece bir kez onaylanıp yayınlanabilir. İşlem seçildiğinde butonlar otomatik olarak kilitlenir.");
    return [];
  }

  // Generate intent (/generate, /create, /post, /new, /yeni, create, üret, olustur)
  if (
    text.startsWith("/generate") ||
    text.startsWith("/create") ||
    text.startsWith("/post") ||
    text.startsWith("/new") ||
    text.startsWith("/yeni") ||
    text.includes("generate") ||
    text.includes("create") ||
    text.includes("üret") ||
    text.includes("uret") ||
    text.includes("oluştur") ||
    text.includes("olustur")
  ) {
    return [{ json: { eventType: "generate", triggerSource: "telegram_command", chatId } }];
  }

  // Unrecognized text message from Telegram: send guidance instead of triggering 2-min generation!
  await sendTg(chatId, "ℹ️ Yazdığınız komutu anlayamadım: <i>"" + rawText + ""</i>\n\n• Yeni post üretmek için: <b>/generate</b> veya <b>/create</b>\n• Son postu yayınlamak için: <b>publish and go</b>\n• Durum için: <b>/status</b>\n• Yardım için: <b>/help</b>");
  return [];
}

// 3. Fallback: Triggered by Schedule (10:00 AM) or Manual Run
return [{ json: { eventType: "generate", triggerSource: "schedule_or_manual", chatId: DEFAULT_CHAT_ID } }];

const CONFIG = {
  brandName: "@developmentserhat",
  instagramAccountId: "17841480124544403",
  spreadsheetId: "1qvPGyBzhp2u8I6TFcaSOAV0BhUmaya6aU6O9kNhchSk",
  sheetName: "Published Content",
