    "Instagram Growth Systems (Hooks, carousels, algorithmic engagement)",
    "Freelance Digital Skills (Selling AI workflows, automation consulting, client acquisition)"
  ]
};

// Persist config to disk so callback executions can always access the spreadsheetId
try {
  const fs = require("fs");
  fs.writeFileSync("/home/node/.n8n-files/studio-images/brand_config.json", JSON.stringify(CONFIG, null, 2));
} catch(e) {}

return [{ json: { ...CONFIG, event: $input.first()?.json || {} } }];

const resp = $input.first()?.json || {};
const rawText = resp.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || "{}";
let draft;
try {
  draft = JSON.parse(rawText);
} catch(e) {
  throw new Error("Agent 1 did not return valid JSON: " + e.message + " | Raw: " + rawText.slice(0, 200));
}

const criticPrompt = `You are the Creative & Visual Art Director for @developmentserhat Instagram content.
Review and elevate this draft from the Content Strategist:
${JSON.stringify(draft, null, 2)}

YOUR CORE OBJECTIVE:
Transform each slide into an AUTHENTIC, NATURAL INSTAGRAM POST GRAPHIC CARD with EMBEDDED TYPOGRAPHY AND TEXT WRITINGS.
The images must NOT look like generic abstract 3D wallpapers or empty photos. They MUST look like real, designed Instagram social media post cards created by a top-tier digital media agency in Figma/Canva, with bold readable typography and graphic design layouts!

FLUX SCHNELL TEXT RENDERING RULES:
