const event = $input.first()?.json || {};
const callbackData = String(event.callbackData || "");
const callbackId = event.callbackId;
const chatId = String(event.chatId || "1519369571");
const eventMessageId = event.messageId;
const botToken = "YOUR_TELEGRAM_BOT_TOKEN";

let action = "unknown";
let draftId = "";

if (callbackData.startsWith("approve")) {
  action = "approve";
  draftId = callbackData.replace("approve_", "").replace("approve", "");
} else if (callbackData.startsWith("redo")) {
  action = "redo";
  draftId = callbackData.replace("redo_", "").replace("redo", "");
} else if (callbackData.startsWith("reject")) {
  action = "reject";
  draftId = callbackData.replace("reject_", "").replace("reject", "");
}

// Multi-Tier Bulletproof Draft Recovery:
let draft = null;
const baseDir = "/home/node/.n8n-files/studio-images";

try {
  const fs = require("fs");
  if (draftId && draftId !== "undefined" && fs.existsSync(baseDir + "/" + draftId + ".json")) {
    draft = JSON.parse(fs.readFileSync(baseDir + "/" + draftId + ".json", "utf8"));
  }
  if (!draft && fs.existsSync(baseDir + "/current_draft.json")) {
    draft = JSON.parse(fs.readFileSync(baseDir + "/current_draft.json", "utf8"));
  }
} catch (e) {
  console.log("Disk recovery note: " + e.message);
}

// Check staticData as Tier 2
const staticData = $getWorkflowStaticData("global");
const drafts = staticData.activeDrafts || {};
if (!draft && draftId && draftId !== "undefined") {
  draft = drafts[draftId] || null;
}
if (!draft && staticData.lastDraft) {
  draft = staticData.lastDraft;
}

// Tier 3: Extract fresh URLs directly from Telegram message text if needed
const rawMsg = String(event.messageText || event.messageCaption || "");
const extractedUrls = [...rawMsg.matchAll(/https:\/\/n8n\.codewaft\.com\/studio-images\/[0-9a-f-]+\.jpg/gi)].map(m => m[0]);

if (extractedUrls.length > 0) {
  const capMatch = rawMsg.match(/(?:📝\s*Instagram Post Caption:\s*
+)([\s\S]*?)(?=
\s*🏷️|
\s*🖼️|
\s*━━━━━━━━━━━━━━━━━━━━━━━━|$)/i);
  const tagMatch = rawMsg.match(/(?:🏷️\s*Hashtags:\s*
+)([\s\S]*?)(?=
\s*🖼️|
\s*━━━━━━━━━━━━━━━━━━━━━━━━|$)/i);

  if (draft) {
    draft.slides = extractedUrls.map((url, idx) => ({
      slideNumber: idx + 1,
      imageUrl: url
    }));
    draft.slideCount = extractedUrls.length;
    if (capMatch) draft.caption = capMatch[1].trim();
    if (tagMatch) draft.hashtags = tagMatch[1].trim();
  } else {
    draft = {
      draftId: draftId || ("draft_" + Date.now()),
      hookTitle: "Daily Instagram Blueprint",
      pillar: "Digital Skills",
      format: extractedUrls.length > 1 ? `Carousel (${extractedUrls.length} slides)` : "Single Post",
      caption: capMatch ? capMatch[1].trim() : "",
      hashtags: tagMatch ? tagMatch[1].trim() : "",
      slides: extractedUrls.map((url, idx) => ({
        slideNumber: idx + 1,
        imageUrl: url
      })),
      slideCount: extractedUrls.length
    };
  }
}

if (!draft || !draft.slides || draft.slides.length === 0) {
  throw new Error("Draft or image URLs not found. Please click /generate to create a fresh post.");
}

// Target messageId to disable/edit buttons
const targetMessageId = eventMessageId || draft.buttonsMessageId;

const updateTelegramButtons = async (btnText, targetUrl) => {
  if (!targetMessageId) return;
  try {
    const inline_keyboard = targetUrl 
      ? [[{ text: btnText, url: targetUrl }]]
      : [[{ text: btnText, callback_data: "locked" }]];
    await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.telegram.org/bot" + botToken + "/editMessageReplyMarkup",
      headers: { "Content-Type": "application/json" },
      body: {
        chat_id: chatId,
        message_id: targetMessageId,
        reply_markup: { inline_keyboard }
      },
      json: true
    });
  } catch (e) {
    console.log("editMessageReplyMarkup error:", e.message);
  }
};

const sendTgNotice = async (text) => {
  try {
    await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.telegram.org/bot" + botToken + "/sendMessage",
      headers: { "Content-Type": "application/json" },
      body: { chat_id: chatId, text, parse_mode: "HTML" },
      json: true
    });
  } catch (e) {}
};

const persistDraft = (d) => {
  try {
    const fs = require("fs");
    fs.writeFileSync(baseDir + "/current_draft.json", JSON.stringify(d, null, 2));
    if (d.draftId) {
      fs.writeFileSync(baseDir + "/" + d.draftId + ".json", JSON.stringify(d, null, 2));
    }
  } catch (e) {
    console.log("Persist draft error: " + e.message);
  }
};

// ==========================================
// STRICT ONE-CHOICE & REPUBLISH LOCK GUARD:
// ==========================================
if (draft.isPublished || draft.status === "published") {
  await updateTelegramButtons("✅ Instagram'da Yayınlandı ↗", "https://www.instagram.com/developmentserhat/");
  await sendTgNotice(`⚠️ <b>Bu taslak zaten Instagram'da yayınlandı!</b>\n━━━━━━━━━━━━━━━━━━━━\n📌 <b>Konu:</b> ${draft.hookTitle || "Instagram Blueprint"}\n🆔 <b>Yayın ID:</b> <code>${draft.publishedMediaId || "N/A"}</code>\n\n🔒 <i>Tekrar yayınlanamaz. Yeni bir gönderi için <b>/generate</b> veya <b>/create</b> yazabilirsiniz.</i>`);
  return []; // STOP THE WORKFLOW IMMEDIATELY
}

if (draft.status === "publishing") {
  await sendTgNotice(`⏳ <b>Bu taslak şu anda Instagram'a yükleniyor...</b>\nLütfen işlemin tamamlanmasını bekleyin.`);
  return []; // STOP
}

if (draft.status === "rejected") {
  await updateTelegramButtons("❌ Reddedildi (Kilitli)");
  await sendTgNotice(`⚠️ <b>Bu taslak daha önce reddedildi.</b>\nYeni bir içerik üretmek için <b>/generate</b> veya <b>/create</b> yazabilirsiniz.`);
  return []; // STOP
}

if (draft.status === "redone") {
  await updateTelegramButtons("🔄 Yeniden Üretildi (Kilitli)");
  await sendTgNotice(`⚠️ <b>Bu taslak için yeniden üretim talep edilmişti.</b>\nYeni taslak üretmek için <b>/generate</b> yazabilirsiniz.`);
  return []; // STOP
}

// LOCK IN THE CHOSEN ACTION AT ONCE:
if (action === "approve") {
  draft.status = "publishing";
  draft.isPublished = true;
  draft.chosenAction = "approve";
  persistDraft(draft);
  await updateTelegramButtons("⏳ Onaylandı — Instagram'a Gönderiliyor...");
} else if (action === "redo") {
  draft.status = "redone";
  draft.chosenAction = "redo";
  persistDraft(draft);
  await updateTelegramButtons("🔄 Yeniden Üretim Seçildi (Kilitli)");
} else if (action === "reject") {
  draft.status = "rejected";
  draft.chosenAction = "reject";
  persistDraft(draft);
  await updateTelegramButtons("❌ Reddedildi (Kilitli)");
}

return [{
  json: {
    action,
    draftId: draft.draftId,
    callbackId,
    chatId,
    messageId: targetMessageId,
    draft
  }
}];

const pubResp = $input.first()?.json || {};
const draft = pubResp.draft || {};
const igMediaId = pubResp.mediaId || "published";

let spreadsheetId = draft.spreadsheetId || "1qvPGyBzhp2u8I6TFcaSOAV0BhUmaya6aU6O9kNhchSk";
let sheetName = draft.sheetName || "Published Content";

// Recover spreadsheetId from disk brand_config if missing from draft
if (!spreadsheetId) {
  try {
    const fs = require("fs");
    const cfgPath = "/home/node/.n8n-files/studio-images/brand_config.json";
    if (fs.existsSync(cfgPath)) {
      const cfg = JSON.parse(fs.readFileSync(cfgPath, "utf8"));
      spreadsheetId = cfg.spreadsheetId;
      sheetName = cfg.sheetName || sheetName;
    }
  } catch (e) {}
}

const isConfigured = Boolean(spreadsheetId && spreadsheetId.trim() !== "");

return [{
  json: {
    spreadsheetId: spreadsheetId || "",
    sheetName: sheetName,
    isSheetConfigured: isConfigured,
    Date: new Date().toISOString().slice(0, 10),
    "Hook / Title": draft.hookTitle || "Instagram Blueprint",
    "Niche Pillar": draft.pillar || "Digital Skills",
    "Format": draft.format || "Single Post",
    "Caption": draft.caption || "",
    "Hashtags": draft.hashtags || "",
    "Visual Prompt": (draft.slides || []).map(s => `[Slide ${s.slideNumber}] ${s.imagePrompt || s.headline || ""}`).join(" | "),
    "Instagram Media ID": igMediaId,
    "Status": "Published"
  }
}];

const resp = $input.first()?.json || {};
let finalPost = null;

// 1. Try to parse Agent 2 creative director output
try {
  const rawText = resp.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || "";
  if (rawText) {
    const cleaned = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();
    finalPost = JSON.parse(cleaned);
  }
} catch(e) {
  finalPost = null;
}

// 2. Resilient Fallback: If Agent 2 experienced a temporary Google API demand spike (503), gracefully fall back to Agent 1 draft
if (!finalPost || !finalPost.hookTitle) {
  try {
    const directorPromptData = $('Prepare Director Prompt').first().json;
    finalPost = directorPromptData.rawDraft || {};
    if (Array.isArray(finalPost.slides)) {
      finalPost.slides = finalPost.slides.map((s, idx) => ({
        ...s,
        slideNumber: s.slideNumber || idx + 1,
        imagePrompt: s.imagePrompt || (s.visualDescription ? `${s.headline}. ${s.visualDescription}` : s.headline)
      }));
    }
  } catch(e) {}
}

if (!finalPost || !finalPost.hookTitle) {
  throw new Error("Unable to extract valid post from Agent 2 or Agent 1 draft.");
}

const config = $("Central Brand Configuration").first().json;
const draftId = "draft_" + Date.now();
const rawSlides = Array.isArray(finalPost.slides) && finalPost.slides.length > 0
  ? finalPost.slides.slice(0, 3)
  : [{ slideNumber: 1, headline: finalPost.hookTitle, imagePrompt: finalPost.hookTitle }];

// Cache the metadata in global staticData so the finalizing node can recombine it
const staticData = $getWorkflowStaticData("global");
staticData.pendingDraft = {
  draftId,
  pillar: finalPost.pillar || "Digital Skills",
  format: finalPost.format || (rawSlides.length > 1 ? `Carousel (${rawSlides.length} slides)` : "Single Post"),
  slideCount: rawSlides.length,
  hookTitle: finalPost.hookTitle,
  caption: finalPost.caption,
  hashtags: finalPost.hashtags,
  spreadsheetId: config.spreadsheetId,
  sheetName: config.sheetName,
  rawSlides,
  createdAt: new Date().toISOString()
};

// Output 1 item per slide with clean prompt
return rawSlides.map((s, idx) => ({
