const results = $input.all().map(item => item.json);
const staticData = $getWorkflowStaticData("global");
const pending = staticData.pendingDraft;
if (!pending) throw new Error("No pending draft metadata found in staticData.");

const urlMap = new Map();
for (const r of results) {
  if (r.slide && r.imageUrl) urlMap.set(Number(r.slide), r.imageUrl);
}

const finalizedSlides = pending.rawSlides.map((s, idx) => {
  const slideNum = s.slideNumber || idx + 1;
  const imageUrl = urlMap.get(Number(slideNum)) || results[idx]?.imageUrl || results[0]?.imageUrl;
  return {
    ...s,
    slideNumber: slideNum,
    imageUrl
  };
});

const draftObj = {
  draftId: pending.draftId,
  pillar: pending.pillar,
  format: pending.format,
  slideCount: finalizedSlides.length,
  hookTitle: pending.hookTitle,
  slides: finalizedSlides,
  caption: pending.caption,
  hashtags: pending.hashtags,
  spreadsheetId: pending.spreadsheetId,
  sheetName: pending.sheetName,
  createdAt: pending.createdAt
};

// 1. Save in staticData
staticData.activeDrafts = staticData.activeDrafts || {};
staticData.activeDrafts[pending.draftId] = draftObj;
staticData.lastDraft = draftObj;

// 2. Persistent disk backup (shared across all runners & manual executions)
try {
  const fs = require("fs");
  const baseDir = "/home/node/.n8n-files/studio-images";
  fs.writeFileSync(baseDir + "/current_draft.json", JSON.stringify(draftObj, null, 2));
  fs.writeFileSync(baseDir + "/" + pending.draftId + ".json", JSON.stringify(draftObj, null, 2));
} catch (e) {
  console.log("Disk backup note: " + e.message);
}

// Clean old drafts (> 24 hours)
const cutoff = Date.now() - 86400000;
for (const [id, d] of Object.entries(staticData.activeDrafts)) {
  if (new Date(d.createdAt).getTime() < cutoff) delete staticData.activeDrafts[id];
}

// Output 1 item per slide so Telegram sends EVERY slide image to preview
return finalizedSlides.map((s, idx) => ({
  json: {
    draftId: pending.draftId,
    chatId: "1519369571",
    slideNumber: s.slideNumber,
    totalSlides: finalizedSlides.length,
    imageUrl: s.imageUrl,
    headline: s.headline || "",
    photoCaption: `📖 <b>Slide ${s.slideNumber} / ${finalizedSlides.length}:</b> ${s.headline || pending.hookTitle}`,
    caption: pending.caption,
    hashtags: pending.hashtags,
    hookTitle: pending.hookTitle,
    pillar: pending.pillar,
    format: pending.format,
    slides: finalizedSlides
  }
}));

const finalItems = $("Finalize Draft & Cache Session").all().map(i => i.json);
const first = finalItems[0] || {};
const slides = first.slides || finalItems.map((item, idx) => ({
  slideNumber: item.slideNumber || idx + 1,
  imageUrl: item.imageUrl
}));

const slideLinks = slides.map(s => `• Slide ${s.slideNumber}: ${s.imageUrl}`).join("\n");

return [{
  json: {
    chatId: "1519369571",
    draftId: first.draftId || ("draft_" + Date.now()),
    hookTitle: first.hookTitle || "Instagram Blueprint",
    pillar: first.pillar || "Digital Skills",
    format: first.format || (slides.length > 1 ? `Carousel (${slides.length} slides)` : "Single Post"),
    caption: first.caption || "",
    hashtags: first.hashtags || "",
    slides: slides,
    slideLinks: slideLinks,
    totalSlides: slides.length
  }
}];

const meta = $("Handle Telegram Callback").first()?.json || {};
const draft = meta.draft;
const chatId = String(meta.chatId || "1519369571");
const buttonsMessageId = meta.messageId || draft?.buttonsMessageId;
const igUserId = "17841480124544403";
const token = "YOUR_INSTAGRAM_GRAPH_API_TOKEN";
const botToken = "YOUR_TELEGRAM_BOT_TOKEN";

if (!draft) throw new Error("Draft expired or not found. Please click /generate to create a new post.");

const slides = draft.slides || [];
if (!slides.length || !slides[0]?.imageUrl) {
  throw new Error("No slide images found in draft to publish. Please click /generate to create a fresh post.");
}

const caption = `${draft.hookTitle}\n\n${draft.caption}\n\n${draft.hashtags}\n\n👉 Follow @developmentserhat for daily digital income blueprints.`;

const postMeta = async (endpoint, bodyObj) => {
  const url = "https://graph.facebook.com/v22.0/" + igUserId + "/" + endpoint;
  let lastErr = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await this.helpers.httpRequest({
        method: "POST",
        url,
        headers: { "Content-Type": "application/json" },
        body: bodyObj,
        json: true
      });
    } catch (err) {
      lastErr = err;
      if (attempt < 3) await new Promise(r => setTimeout(r, 2000 * attempt));
    }
  }
  const errData = lastErr.response?.data || lastErr.cause?.response?.data || lastErr.context?.data || {};
  const detail = errData?.error?.error_user_msg || errData?.error?.message || lastErr.message || JSON.stringify(errData);
  throw new Error("Meta API Error (" + endpoint + "): " + detail);
};

const pollStatus = async (containerId) => {
  const url = "https://graph.facebook.com/v22.0/" + containerId + "?fields=status_code,status&access_token=" + token;
  for (let i = 0; i < 20; i++) {
    await new Promise(r => setTimeout(r, 3000));
    try {
      const data = await this.helpers.httpRequest({ method: "GET", url, json: true });
      if (data?.status_code === "FINISHED") return true;
      if (data?.status_code === "ERROR" || data?.status_code === "EXPIRED") {
        throw new Error("Media container failed [" + data.status_code + "]: " + (data.status || JSON.stringify(data)));
      }
    } catch (e) {
      if (e.message.startsWith("Media container failed")) throw e;
    }
  }
  throw new Error("Media container did not finish processing within 60 seconds (container: " + containerId + ")");
};

let publishedMediaId = null;
let isCarousel = false;
const slideCount = slides.length;

if (slideCount >= 2) {
  isCarousel = true;
  const itemIds = [];
  for (const slide of slides) {
    const itemRes = await postMeta("media", {
      image_url: slide.imageUrl,
      is_carousel_item: true,
      access_token: token
    });
    if (!itemRes.id) throw new Error("Failed to create carousel item for slide " + slide.slideNumber);
    await pollStatus(itemRes.id);
    itemIds.push(itemRes.id);
  }

  const parentRes = await postMeta("media", {
    media_type: "CAROUSEL",
    children: itemIds.join(","),
    caption,
    access_token: token
  });
  if (!parentRes.id) throw new Error("Failed to create parent carousel container");
  await pollStatus(parentRes.id);

  const pubRes = await postMeta("media_publish", {
    creation_id: parentRes.id,
    access_token: token
  });
  if (!pubRes.id) throw new Error("Failed to publish carousel container");
  publishedMediaId = pubRes.id;
} else {
  // Single image post
  const firstUrl = slides[0].imageUrl;
  const createRes = await postMeta("media", {
    image_url: firstUrl,
    caption,
    access_token: token
  });
  if (!createRes.id) throw new Error("Failed to create single media container");
  await pollStatus(createRes.id);

  const pubRes = await postMeta("media_publish", {
    creation_id: createRes.id,
    access_token: token
  });
  if (!pubRes.id) throw new Error("Failed to publish single media container");
  publishedMediaId = pubRes.id;
}

// Persist published state permanently
draft.status = "published";
draft.isPublished = true;
draft.publishedMediaId = publishedMediaId;
draft.publishedAt = new Date().toISOString();

try {
  const fs = require("fs");
  const baseDir = "/home/node/.n8n-files/studio-images";
  fs.writeFileSync(baseDir + "/current_draft.json", JSON.stringify(draft, null, 2));
  if (draft.draftId) {
    fs.writeFileSync(baseDir + "/" + draft.draftId + ".json", JSON.stringify(draft, null, 2));
  }
} catch (e) {
  console.log("Save published draft error: " + e.message);
}

// Update the Telegram button to point directly to the published Instagram link!
if (buttonsMessageId) {
  try {
    await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.telegram.org/bot" + botToken + "/editMessageReplyMarkup",
      headers: { "Content-Type": "application/json" },
      body: {
        chat_id: chatId,
        message_id: buttonsMessageId,
        reply_markup: {
          inline_keyboard: [
            [
              {
                text: "✅ Instagram'da Yayınlandı ↗",
                url: "https://www.instagram.com/developmentserhat/"
              }
            ]
          ]
        }
      },
      json: true
    });
  } catch (e) {
    console.log("Update final published button error: " + e.message);
  }
}

return [{
  json: {
    chatId,
    draft,
    mediaId: publishedMediaId || "N/A",
    isCarousel,
    slideCount,
    permalink: "https://www.instagram.com/developmentserhat/",
    publishedAt: new Date().toISOString()
  }
}];

const res = $input.first()?.json || {};
const messageId = res.message_id;
const draftId = $('Prepare Decision Card').first()?.json?.draftId;

if (messageId && draftId) {
  try {
    const fs = require('fs');
    const baseDir = '/home/node/.n8n-files/studio-images';
    const draftPath = baseDir + '/' + draftId + '.json';
    if (fs.existsSync(draftPath)) {
      const d = JSON.parse(fs.readFileSync(draftPath, 'utf8'));
      d.buttonsMessageId = messageId;
      fs.writeFileSync(draftPath, JSON.stringify(d, null, 2));
    }
    const curPath = baseDir + '/current_draft.json';
    if (fs.existsSync(curPath)) {
      const d = JSON.parse(fs.readFileSync(curPath, 'utf8'));
      d.buttonsMessageId = messageId;
      fs.writeFileSync(curPath, JSON.stringify(d, null, 2));
    }
  } catch (e) {
    console.log('Record button ID error: ' + e.message);
  }
}

return $input.all();
